Here's an example C++ function that takes a reference to a std::string containing Markdown formatted text and returns a std::string containing HTML formatted text:

```cpp
#include <string>
#include <iostream>
#include <sstream>
#include <vector>
#include <algorithm>

// Helper function to convert Markdown headings to HTML
std::string convertHeading(const std::string& input) {
    std::string output = "<h" + std::to_string(input.find_first_of('#')) + ">";
    output += input.substr(1);
    output += "</h" + std::to_string(input.find_first_of('#')) + ">";
    return output;
}

// Helper function to convert Markdown lists to HTML
std::string convertList(const std::string& input) {
    std::stringstream ss(input);
    std::string item;
    std::vector<std::string> list_items;
    while (std::getline(ss, item, '\n')) {
        item.erase(item.find_last_not_of(" \t") + 1);
        if (item.empty()) {
            continue;
        }
        list_items.push_back(item);
    }

    std::string output = "<ul>";
    for (const auto& item : list_items) {
        std::string bullet = item.find_first_of('*') != std::string::npos ? "<li>" : "<ul>";
        output += bullet;
        output += item.substr(item.find_first_of('*') + 1);
        output += "</li>";
    }
    output += "</ul>";
    return output;
}

// Helper function to convert Markdown links to HTML
std::string convertLink(const std::string& input) {
    std::size_t start_pos = input.find_first_of("(");
    std::size_t end_pos = input.find_first_of(")", start_pos);
    if (start_pos == std::string::npos || end_pos == std::string::npos) {
        return input;
    }
    std::string link_text = input.substr(0, start_pos);
    std::string href = input.substr(start_pos + 1, end_pos - start_pos - 1);
    std::string output = "<a href=\"" + href + "\">" + link_text + "</a>";
    return output;
}

// Main function to convert Markdown to HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream ss(markdown);
    std::string line;
    std::string html = "";

    while (std::getline(ss, line)) {
        line.erase(line.find_last_not_of(" \t") + 1);
        if (line.empty()) {
            html += "\n";
            continue;
        }

        // Convert headings to HTML
        if (line[0] == '#') {
            html += convertHeading(line) + "\n";
            continue;
        }

        // Convert lists to HTML
        if (line[0] == '*' || line[0] == '-') {
            html += convertList(line) + "\n";
            continue;
        }

        // Convert links to HTML
        html += convertLink(line) + "\n";
    }

    return html;
}

int main() {
    std::string markdown = "Hello, #world! This is a *list*:\n- Item 1\n- Item 2\n[Link](https://example.com)";

    std::string html = convertMarkdownToHtml(markdown);

    std::cout << "Markdown:\n" << markdown << "\n";
    std::cout << "HTML:\n" << html << "\n";

    return 0;
}
```

This function uses several helper functions to convert Markdown headings, lists, and links to their corresponding HTML formats. The main `convertMarkdownToHtml` function reads the input Markdown line by line, applies the appropriate conversion functions, and concatenates the resulting HTML into a single string. 

Note that this implementation is not exhaustive and only covers a subset of Markdown syntax. You may need to extend or modify the helper functions to handle additional Markdown features as needed.

